#include <stdio.h>
#include <math.h>
#include <random>
int P[20]={7,8,6,15,8,13,13,12,13,13,7,15,12,8,10,10,14,12,8,9};
int S[20]={199,155,231,156,183,242,165,155,210,248,164,221,239,192,247,229,241,186,202,156};
double corr(double*u, int*obs, int off, int stride){
    double xs[20], ys[20];
    for(int s=1;s<=20;s++){xs[s-1]=u[(s-1)*64+off];ys[s-1]=obs[s-1];}
    double mx=0,my=0;for(int i=0;i<20;i++){mx+=xs[i];my+=ys[i];}mx/=20;my/=20;
    double num=0,dx=0,dy=0;
    for(int i=0;i<20;i++){num+=(xs[i]-mx)*(ys[i]-my);dx+=(xs[i]-mx)*(xs[i]-mx);dy+=(ys[i]-my)*(ys[i]-my);}
    return num/sqrt(dx*dy);
}
int main(){
    static double u[20*64];
    for(int s=1;s<=20;s++){std::mt19937 mt(s);for(int i=0;i<64;i++)u[(s-1)*64+i]=mt()/4294967296.0;}
