    for(int tr=0;tr<3;tr++)
    for(int comb=0;comb<2;comb++)
    for(int fin=0;fin<3;fin++)
    for(int Kmode=0;Kmode<3;Kmode++) // 0: fixed K, 1: K=1+floor(u0*K), 2: K=1+floor(u0*K/2)...
